rep('''    private void loadBitmaps(){\n        floorJunk=decode(R.drawable.floor_junkyard);floorFoundry=decode(R.drawable.floor_foundry);floorReactor=decode(R.drawable.floor_reactor);\n        core=decode(R.drawable.core);cannon=decode(R.drawable.cannon);blade=decode(R.drawable.blade);armor=decode(R.drawable.armor);battery=decode(R.drawable.battery);wheel=decode(R.drawable.wheel);tesla=decode(R.drawable.tesla);rocket=decode(R.drawable.rocket);shield=decode(R.drawable.shield);laser=decode(R.drawable.laser);\n        drone=decode(R.drawable.drone);heavy=decode(R.drawable.heavy);sniper=decode(R.drawable.sniper);rammer=decode(R.drawable.rammer);\n        bossCrusher=decode(R.drawable.boss_crusher);bossMagnetar=decode(R.drawable.boss_magnetar);bossForge=decode(R.drawable.boss_forge);pickupGlow=decode(R.drawable.pickup_glow);\n    }\n    private void loadMeta(){scrap=prefs.getInt("scrap",0);for(int i=0;i<meta.length;i++)meta[i]=prefs.getInt("m"+i,0);}\n    private void saveMeta(){SharedPreferences.Editor e=prefs.edit().putInt("scrap",scrap);for(int i=0;i<meta.length;i++)e.putInt("m"+i,meta[i]);e.apply();}''','''    private void loadBitmaps(){\n        floorJunk=decode(R.drawable.floor_junkyard);floorFoundry=decode(R.drawable.floor_foundry);floorReactor=decode(R.drawable.floor_reactor);floorWasteland=decode(R.drawable.floor_wasteland);floorLab=decode(R.drawable.floor_lab);\n        core=decode(R.drawable.core);cannon=decode(R.drawable.cannon);blade=decode(R.drawable.blade);armor=decode(R.drawable.armor);battery=decode(R.drawable.battery);wheel=decode(R.drawable.wheel);tesla=decode(R.drawable.tesla);rocket=decode(R.drawable.rocket);shield=decode(R.drawable.shield);laser=decode(R.drawable.laser);shotgun=decode(R.drawable.shotgun);plasma=decode(R.drawable.plasma);mortar=decode(R.drawable.mortar);\n        drone=decode(R.drawable.drone);heavy=decode(R.drawable.heavy);sniper=decode(R.drawable.sniper);rammer=decode(R.drawable.rammer);swarmer=decode(R.drawable.swarmer);bomber=decode(R.drawable.bomber);scrapper=decode(R.drawable.scrapper);\n        bossCrusher=decode(R.drawable.boss_crusher);bossMagnetar=decode(R.drawable.boss_magnetar);bossForge=decode(R.drawable.boss_forge);bossArtillery=decode(R.drawable.boss_artillery);bossStorm=decode(R.drawable.boss_storm);pickupGlow=decode(R.drawable.pickup_glow);\n        projBullet=decode(R.drawable.proj_bullet);projRocket=decode(R.drawable.proj_rocket);projPlasma=decode(R.drawable.proj_plasma);projMortar=decode(R.drawable.proj_mortar);projEnemy=decode(R.drawable.proj_enemy);\n        propCrate=decode(R.drawable.prop_crate);propPipe=decode(R.drawable.prop_pipe);propBeacon=decode(R.drawable.prop_beacon);propScrap=decode(R.drawable.prop_scrap);\n    }\n    private void loadMeta(){scrap=prefs.getInt("scrap",0);tutorialDone=prefs.getBoolean("tutorial_done_v5",false);for(int i=0;i<meta.length;i++)meta[i]=prefs.getInt("m"+i,0);}\n    private void saveMeta(){SharedPreferences.Editor e=prefs.edit().putInt("scrap",scrap).putBoolean("tutorial_done_v5",tutorialDone);for(int i=0;i<meta.length;i++)e.putInt("m"+i,meta[i]);e.apply();}''')

