old_start='''    private void startRun(){\n        enemies.clear();projectiles.clear();parts.clear();pickups.clear();fx.clear();px=VW*.5f;py=VH*.53f;heading=-1.5708f;\n        maxHp=115+meta[0]*18;hp=maxHp;maxShield=meta[4]*14;shieldHp=maxShield;\n        wave=1;score=kills=combo=bestCombo=0;comboTimer=0;hitCd=shieldDelay=empCd=fireCd=teslaCd=rocketCd=laserCd=0;cameraShake=0;\n        rerolls=1+meta[5]/3;addPart(CANNON);addPart(ARMOR);addPart(WHEEL);if(meta[4]>0)addPart(SHIELD);\n        state=PLAY;tutorialTimer=6.5f;startWave();toast="ПРИТЯГИВАЙ ДЕТАЛИ • СОБИРАЙ МАШИНУ";toastTimer=2.4f;\n    }\n    private void startWave(){waveClearTimer=0;spawnTimer=.25f;spawnLeft=(wave%5==0)?1:5+wave*2;toast=wave%5==0?"⚠ БОСС • ВОЛНА "+wave:"ВОЛНА "+wave;toastTimer=wave%5==0?2.1f:1.15f;}'''
new_start='''    private void startRun(){if(!tutorialDone){startTutorial();return;}beginNormalRun();}\n    private void beginNormalRun(){\n        tutorialMode=false;enemies.clear();projectiles.clear();parts.clear();pickups.clear();fx.clear();px=VW*.5f;py=VH*.53f;heading=-1.5708f;\n        maxHp=115+meta[0]*18;hp=maxHp;maxShield=meta[4]*14;shieldHp=maxShield;\n        wave=1;score=kills=combo=bestCombo=0;comboTimer=0;hitCd=shieldDelay=empCd=0;cameraShake=0;\n        rerolls=1+meta[5]/3;addPart(CANNON);addPart(ARMOR);addPart(WHEEL);if(meta[4]>0)addPart(SHIELD);\n        state=PLAY;startWave();toast="СОБИРАЙ МОДУЛИ • СТРОЙ БОЕВУЮ МАШИНУ";toastTimer=2.2f;\n    }\n    private void startTutorial(){\n        tutorialMode=true;tutorialStep=0;tutorialMoved=0;enemies.clear();projectiles.clear();parts.clear();pickups.clear();fx.clear();px=VW*.42f;py=VH*.55f;heading=0;\n        maxHp=150;hp=maxHp;maxShield=0;shieldHp=0;wave=0;score=kills=combo=bestCombo=0;spawnLeft=0;hitCd=empCd=0;cameraShake=0;\n        addPart(CANNON);addPart(ARMOR);addPart(WHEEL);tutorialPartBase=parts.size();state=PLAY;toast="ОБУЧЕНИЕ • 1/5";toastTimer=1.2f;\n    }\n    private void finishTutorial(boolean skipped){\n        tutorialDone=true;tutorialMode=false;saveMeta();enemies.clear();projectiles.clear();pickups.clear();fx.clear();wave=1;hp=maxHp;empCd=0;state=PLAY;startWave();toast=skipped?"ОБУЧЕНИЕ ПРОПУЩЕНО":"ОБУЧЕНИЕ ЗАВЕРШЕНО • ДОБРО ПОЖАЛОВАТЬ НА АРЕНУ";toastTimer=2.4f;\n    }\n    private void startWave(){waveClearTimer=0;spawnTimer=.25f;spawnLeft=(wave%5==0)?1:5+wave*2;toast=wave%5==0?"⚠ БОСС • ВОЛНА "+wave:"ВОЛНА "+wave;toastTimer=wave%5==0?2.1f:1.15f;}'''
rep(old_start,new_start)

old_update='''    private void update(float dt){\n        float jx=0,jy=0;if(joyActive){float dx=joyX-joyBaseX,dy=joyY-joyBaseY,len=(float)Math.sqrt(dx*dx+dy*dy);if(len>8){float m=Math.min(1,len/95f);jx=dx/len*m;jy=dy/len*m;}}\n        float speed=285+meta[3]*18+countPart(WHEEL)*17;px+=jx*speed*dt;py+=jy*speed*dt;if(Math.abs(jx)+Math.abs(jy)>.06f)heading=(float)Math.atan2(jy,jx);px=clamp(px,90,VW-90);py=clamp(py,100,VH-90);\n        if(empCd>0)empCd-=dt;if(hitCd>0)hitCd-=dt;if(shieldDelay>0)shieldDelay-=dt;else if(shieldHp<maxShield)shieldHp=Math.min(maxShield,shieldHp+(16+countPart(SHIELD)*3)*dt);if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0)combo=0;}cameraShake=Math.max(0,cameraShake-30*dt);\n        spawnTimer-=dt;if(spawnLeft>0&&spawnTimer<=0){spawnEnemy();spawnLeft--;spawnTimer=wave%5==0?99:Math.max(.24f,.65f-wave*.013f);}\n        updateEnemies(dt);updatePickups(dt);updateWeapons(dt);updateProjectiles(dt);updateFx(dt);\n        if(spawnLeft==0&&enemies.isEmpty()){waveClearTimer+=dt;if(waveClearTimer>1.1f){rollChoices();state=UPGRADE;joyActive=false;joyPointer=-1;}}\n        if(hp<=0&&state==PLAY){hp=0;state=GAMEOVER;joyActive=false;joyPointer=-1;int reward=Math.max(10,wave*5+kills/4+bestCombo);scrap+=reward;saveMeta();toast="+"+reward+" ЛОМА";toastTimer=3;haptic(55);}\n    }'''
new_update='''    private void update(float dt){\n        float jx=0,jy=0;if(joyActive){float dx=joyX-joyBaseX,dy=joyY-joyBaseY,len=(float)Math.sqrt(dx*dx+dy*dy);if(len>8){float m=Math.min(1,len/95f);jx=dx/len*m;jy=dy/len*m;}}\n        float speed=285+meta[3]*18+countPart(WHEEL)*17;px+=jx*speed*dt;py+=jy*speed*dt;if(Math.abs(jx)+Math.abs(jy)>.06f){heading=(float)Math.atan2(jy,jx);if(tutorialMode&&tutorialStep==0)tutorialMoved+=speed*dt*(float)Math.sqrt(jx*jx+jy*jy);}px=clamp(px,90,VW-90);py=clamp(py,100,VH-90);\n        if(empCd>0)empCd-=dt;if(hitCd>0)hitCd-=dt;if(shieldDelay>0)shieldDelay-=dt;else if(shieldHp<maxShield)shieldHp=Math.min(maxShield,shieldHp+(16+countPart(SHIELD)*3)*dt);if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0)combo=0;}cameraShake=Math.max(0,cameraShake-30*dt);\n        if(!tutorialMode){spawnTimer-=dt;if(spawnLeft>0&&spawnTimer<=0){spawnEnemy();spawnLeft--;spawnTimer=wave%5==0?99:Math.max(.24f,.65f-wave*.013f);}}\n        updateEnemies(dt);updatePickups(dt);updateWeapons(dt);updateBlades(dt);updateProjectiles(dt);updateFx(dt);if(tutorialMode)updateTutorial(dt);\n        if(!tutorialMode&&spawnLeft==0&&enemies.isEmpty()){waveClearTimer+=dt;if(waveClearTimer>1.1f){rollChoices();state=UPGRADE;joyActive=false;joyPointer=-1;}}\n        if(hp<=0&&state==PLAY&&!tutorialMode){hp=0;state=GAMEOVER;joyActive=false;joyPointer=-1;int reward=Math.max(10,wave*5+kills/4+bestCombo);scrap+=reward;saveMeta();toast="+"+reward+" ЛОМА";toastTimer=3;haptic(55);}\n    }\n    private void updateTutorial(float dt){\n        if(tutorialStep==0&&tutorialMoved>145){tutorialStep=1;spawnPickup(Math.min(VW-180,px+340),py-35,SHOTGUN);toast="ОБУЧЕНИЕ • 2/5";toastTimer=1;}\n    }\n    private void tutorialPickupConnected(){if(tutorialMode&&tutorialStep==1){tutorialStep=2;Enemy d=new Enemy();d.type=0;d.tutorial=true;d.radius=38;d.maxHp=d.hp=90;d.speed=0;d.x=Math.min(VW-180,px+500);d.y=py;enemies.add(d);toast="ОБУЧЕНИЕ • 3/5";toastTimer=1;}}\n    private void tutorialDummyDestroyed(){if(tutorialMode&&tutorialStep==2){tutorialStep=3;for(int i=0;i<3;i++){Enemy d=new Enemy();d.type=4;d.tutorial=true;d.radius=30;d.maxHp=d.hp=70;d.speed=0;float a=(float)(i*Math.PI*2/3);d.x=px+(float)Math.cos(a)*270;d.y=py+(float)Math.sin(a)*210;enemies.add(d);}empCd=0;toast="ОБУЧЕНИЕ • 4/5";toastTimer=1;}}'''
rep(old_update,new_update)

start=s.index('    private void spawnEnemy(){')
end=s.index('    private void updatePickups(float dt){')
new_enemy='''    private void spawnEnemy(){\n        Enemy e=new Enemy();float side=rng.nextFloat();if(side<.25){e.x=-110;e.y=rng.nextFloat()*VH;}else if(side<.5){e.x=VW+110;e.y=rng.nextFloat()*VH;}else if(side<.75){e.x=rng.nextFloat()*VW;e.y=-110;}else{e.x=rng.nextFloat()*VW;e.y=VH+110;}\n        if(wave%5==0){e.type=10+((wave/5-1)%5);e.radius=98;e.maxHp=560+wave*92;e.speed=46+wave*.85f;e.phase=rng.nextFloat()*6.28f;if(e.type==13)e.speed*=.78f;if(e.type==14)e.speed*=1.18f;}\n        else{float r=rng.nextFloat();if(wave>=10&&r<.12){e.type=6;e.radius=36;e.maxHp=72+wave*9;e.speed=105;}else if(wave>=8&&r<.25){e.type=5;e.radius=38;e.maxHp=74+wave*8;e.speed=98;}else if(wave>=6&&r<.39){e.type=4;e.radius=28;e.maxHp=34+wave*5;e.speed=148;}else if(wave>=7&&r<.53){e.type=2;e.radius=35;e.maxHp=60+wave*8;e.speed=75;}else if(wave>=4&&r<.72){e.type=1;e.radius=48;e.maxHp=110+wave*12;e.speed=51;}else if(wave>=9&&r<.84){e.type=3;e.radius=36;e.maxHp=76+wave*8;e.speed=123;}else{e.type=0;e.radius=35;e.maxHp=45+wave*7;e.speed=82+wave*1.8f;}if(wave>=3&&rng.nextFloat()<Math.min(.31f,.05f+wave*.013f)){e.elite=true;e.maxHp*=1.8f;e.speed*=1.12f;e.radius*=1.1f;}}\n        e.hp=e.maxHp;e.shootCd=.6f+rng.nextFloat();enemies.add(e);\n    }\n\n    private void updateEnemies(float dt){\n        ArrayList<Enemy> pending=new ArrayList<>();Iterator<Enemy> it=enemies.iterator();while(it.hasNext()){Enemy e=it.next();e.phase+=dt;\n            if(e.stun>0)e.stun-=dt;else if(!e.tutorial){\n                float dx=px-e.x,dy=py-e.y,d=Math.max(1,dist(px,py,e.x,e.y)),ux=dx/d,uy=dy/d;\n                if(e.type==2&&d<560){if(d<370){e.x-=ux*e.speed*.5f*dt;e.y-=uy*e.speed*.5f*dt;}e.shootCd-=dt;if(e.shootCd<=0){enemyShot(e,ux,uy);e.shootCd=Math.max(.82f,1.6f-wave*.022f);}}\n                else if(e.type==3){e.shootCd-=dt;float boost=e.shootCd<0?2.5f:1f;e.x+=ux*e.speed*boost*dt;e.y+=uy*e.speed*boost*dt;if(e.shootCd<-0.7f)e.shootCd=1.45f;}\n                else if(e.type==4){float tx=-uy,ty=ux,wob=(float)Math.sin(e.phase*6)*.65f;e.x+=(ux+tx*wob)*e.speed*dt;e.y+=(uy+ty*wob)*e.speed*dt;}\n                else if(e.type==5){e.x+=ux*e.speed*.88f*dt;e.y+=uy*e.speed*.88f*dt;e.shootCd-=dt;if(d<150&&e.shootCd<=0){damagePlayer(20+wave*.45f);explosionFx(e.x,e.y,Color.rgb(255,123,52),125);e.hp=0;e.shootCd=99;}}\n                else if(e.type==6){Pickup target=nearestPickup(e.x,e.y);if(target!=null){float pd=Math.max(1,dist(e.x,e.y,target.x,target.y));e.x+=(target.x-e.x)/pd*e.speed*dt;e.y+=(target.y-e.y)/pd*e.speed*dt;if(pd<42){pickups.remove(target);e.hp=Math.min(e.maxHp,e.hp+28);particleBurst(e.x,e.y,Color.rgb(242,173,65),8);}}else{e.x+=ux*e.speed*dt;e.y+=uy*e.speed*dt;}}\n                else if(e.type==11){float tx=-uy,ty=ux;e.x+=(ux*.65f+tx*(float)Math.sin(e.phase)*.35f)*e.speed*dt;e.y+=(uy*.65f+ty*(float)Math.sin(e.phase)*.35f)*e.speed*dt;for(Pickup q:pickups){float pd=dist(e.x,e.y,q.x,q.y);if(pd<330&&pd>4){q.vx+=(e.x-q.x)/pd*95*dt;q.vy+=(e.y-q.y)/pd*95*dt;}}}\n                else if(e.type==12){e.x+=ux*e.speed*.7f*dt;e.y+=uy*e.speed*.7f*dt;e.shootCd-=dt;if(e.shootCd<=0&&enemies.size()+pending.size()<18){pending.add(makeMinion(e.x,e.y));pending.add(makeMinion(e.x,e.y));e.shootCd=2.6f;}}\n                else if(e.type==13){if(d<470){e.x-=ux*e.speed*.5f*dt;e.y-=uy*e.speed*.5f*dt;}else if(d>610){e.x+=ux*e.speed*.65f*dt;e.y+=uy*e.speed*.65f*dt;}e.shootCd-=dt;if(e.shootCd<=0){enemyArtillery(e);e.shootCd=2.0f;}}\n                else if(e.type==14){float tx=-uy,ty=ux;e.x+=(ux*.42f+tx*.78f)*e.speed*dt;e.y+=(uy*.42f+ty*.78f)*e.speed*dt;e.shootCd-=dt;if(e.shootCd<=0){stormPulse(e);e.shootCd=2.2f;}}\n                else{e.x+=ux*e.speed*dt;e.y+=uy*e.speed*dt;}\n                if(d<e.radius+62&&e.type!=2&&e.type!=13){if(hitCd<=0){damagePlayer(isBoss(e)?26:(e.type==1?18:12));hitCd=.52f;e.x-=ux*46;e.y-=uy*46;}}\n            }\n            if(e.flash>0)e.flash-=dt;if(e.hp<=0){boolean td=e.tutorial&&tutorialStep==2;killEnemy(e);it.remove();if(td)tutorialDummyDestroyed();}\n        }\n        if(!pending.isEmpty())enemies.addAll(pending);\n    }\n    private Enemy makeMinion(float x,float y){Enemy m=new Enemy();m.type=0;m.radius=33;m.maxHp=40+wave*5;m.hp=m.maxHp;m.speed=92;m.x=x+rng.nextFloat()*130-65;m.y=y+rng.nextFloat()*130-65;return m;}\n    private void enemyShot(Enemy e,float ux,float uy){Projectile q=new Projectile();q.hostile=true;q.x=e.x+ux*34;q.y=e.y+uy*34;q.prevX=q.x;q.prevY=q.y;q.vx=ux*285;q.vy=uy*285;q.damage=10+wave*.6f;q.life=5;q.radius=9;q.type=3;q.angle=(float)Math.atan2(uy,ux);projectiles.add(q);}\n    private void enemyArtillery(Enemy e){for(int i=-1;i<=1;i++){float a=(float)Math.atan2(py-e.y,px-e.x)+i*.18f;Projectile q=new Projectile();q.hostile=true;q.type=7;q.x=e.x;q.y=e.y;q.prevX=q.x;q.prevY=q.y;q.vx=(float)Math.cos(a)*235;q.vy=(float)Math.sin(a)*235;q.damage=12+wave*.55f;q.splash=72;q.life=4;q.radius=12;q.angle=a;projectiles.add(q);}muzzleFx(e.x,e.y,(float)Math.atan2(py-e.y,px-e.x),Color.rgb(255,128,65));}\n    private void stormPulse(Enemy e){Fx f=new Fx();f.kind=6;f.x=e.x;f.y=e.y;f.life=f.max=.7f;fx.add(f);if(dist(e.x,e.y,px,py)<390)damagePlayer(9+wave*.35f);for(Part s:parts)s.cd+=.08f;cameraShake=Math.max(cameraShake,5);}\n    private boolean isBoss(Enemy e){return e.type>=10;}\n    private Pickup nearestPickup(float x,float y){Pickup best=null;float bd=99999;for(Pickup q:pickups){float d=dist(x,y,q.x,q.y);if(d<bd){bd=d;best=q;}}return best;}\n\n'''
s=s[:start]+new_enemy+s[end:]

