new_weapons='''    private void updateWeapons(float dt){\n        int bats=countPart(BATTERY);float power=1+meta[2]*.09f,rate=1+bats*.055f;for(Part s:parts){s.cd-=dt;if(!isRangedWeapon(s.type))continue;float[]mp=partPos(s);Enemy t=nearestEnemy(mp[0],mp[1]);if(t==null)continue;float a=(float)Math.atan2(t.y-mp[1],t.x-mp[0]);s.aim=a;if(s.cd>0)continue;\n            if(s.type==CANNON){fireBullet(mp[0],mp[1],a,18*power,0);s.cd=.52f/rate;}\n            else if(s.type==SHOTGUN){for(int k=-2;k<=2;k++)fireBullet(mp[0],mp[1],a+k*.105f,10.5f*power,2);s.cd=1.05f/rate;cameraShake=Math.max(cameraShake,3);}\n            else if(s.type==PLASMA){firePlasma(mp[0],mp[1],a,34*power);s.cd=.88f/rate;}\n            else if(s.type==ROCKET){fireRocket(mp[0],mp[1],a,42*power);s.cd=1.62f/rate;}\n            else if(s.type==TESLA){teslaZapFrom(mp[0],mp[1],22*power,1+Math.min(5,countPart(TESLA)));s.cd=1.08f/rate;}\n            else if(s.type==LASER){damageEnemy(t,32*power);Fx f=new Fx();f.kind=2;f.x=mp[0];f.y=mp[1];f.x2=t.x;f.y2=t.y;f.life=f.max=.13f;fx.add(f);muzzleFx(mp[0],mp[1],a,Color.rgb(85,255,233));s.cd=.66f/rate;}\n            else if(s.type==MORTAR){fireMortar(mp[0],mp[1],t.x,t.y,52*power);s.cd=1.78f/rate;}\n        }\n    }\n    private boolean isRangedWeapon(int t){return t==CANNON||t==TESLA||t==ROCKET||t==LASER||t==SHOTGUN||t==PLASMA||t==MORTAR;}\n    private float[] partPos(Part s){float ca=(float)Math.cos(heading),sa=(float)Math.sin(heading),ox=SLOTS[s.slot][0],oy=SLOTS[s.slot][1];return new float[]{px+ox*ca-oy*sa,py+ox*sa+oy*ca};}\n    private void fireBullet(float x,float y,float a,float damage,int type){Projectile q=new Projectile();q.type=type;q.x=x+(float)Math.cos(a)*42;q.y=y+(float)Math.sin(a)*42;q.prevX=q.x;q.prevY=q.y;q.vx=(float)Math.cos(a)*(type==2?610:690);q.vy=(float)Math.sin(a)*(type==2?610:690);q.damage=damage;q.life=1.8f;q.radius=type==2?5:6;q.angle=a;projectiles.add(q);muzzleFx(x,y,a,type==2?Color.rgb(255,196,96):Color.rgb(90,255,235));}\n    private void fireRocket(float x,float y,float a,float damage){Projectile q=new Projectile();q.type=1;q.x=x+(float)Math.cos(a)*38;q.y=y+(float)Math.sin(a)*38;q.prevX=q.x;q.prevY=q.y;q.vx=(float)Math.cos(a)*310;q.vy=(float)Math.sin(a)*310;q.damage=damage;q.life=4;q.radius=12;q.splash=102;q.angle=a;projectiles.add(q);muzzleFx(x,y,a,Color.rgb(255,151,57));}\n    private void firePlasma(float x,float y,float a,float damage){Projectile q=new Projectile();q.type=4;q.x=x+(float)Math.cos(a)*38;q.y=y+(float)Math.sin(a)*38;q.prevX=q.x;q.prevY=q.y;q.vx=(float)Math.cos(a)*440;q.vy=(float)Math.sin(a)*440;q.damage=damage;q.life=2.7f;q.radius=13;q.splash=72;q.angle=a;projectiles.add(q);muzzleFx(x,y,a,Color.rgb(184,103,255));}\n    private void fireMortar(float x,float y,float tx,float ty,float damage){float a=(float)Math.atan2(ty-y,tx-x);Projectile q=new Projectile();q.type=5;q.x=x;q.y=y;q.prevX=x;q.prevY=y;q.targetX=tx;q.targetY=ty;q.vx=(float)Math.cos(a)*250;q.vy=(float)Math.sin(a)*250;q.damage=damage;q.life=3.3f;q.radius=15;q.splash=138;q.angle=a;projectiles.add(q);muzzleFx(x,y,a,Color.rgb(255,207,96));}\n    private void teslaZapFrom(float sx,float sy,float damage,int chains){ArrayList<Enemy> hit=new ArrayList<>();for(int chain=0;chain<chains;chain++){Enemy best=null;float bd=chain==0?540:310;for(Enemy e:enemies){if(hit.contains(e))continue;float d=dist(sx,sy,e.x,e.y);if(d<bd){bd=d;best=e;}}if(best==null)break;damageEnemy(best,damage*(1-chain*.09f));Fx f=new Fx();f.kind=1;f.x=sx;f.y=sy;f.x2=best.x;f.y2=best.y;f.life=f.max=.19f;fx.add(f);hit.add(best);sx=best.x;sy=best.y;}muzzleFx(sx,sy,0,Color.rgb(97,255,242));}\n    private void updateBlades(float dt){for(Part s:parts){if(s.type!=BLADE)continue;float[]mp=partPos(s);for(Enemy e:enemies)if(dist(mp[0],mp[1],e.x,e.y)<e.radius+48)damageEnemy(e,(30+meta[2]*2.2f)*dt);}}\n    private void muzzleFx(float x,float y,float a,int color){Fx f=new Fx();f.kind=4;f.x=x+(float)Math.cos(a)*43;f.y=y+(float)Math.sin(a)*43;f.x2=a;f.color=color;f.life=f.max=.10f;fx.add(f);}\n    private void explosionFx(float x,float y,int color,float size){particleBurst(x,y,color,18);Fx f=new Fx();f.kind=5;f.x=x;f.y=y;f.x2=size;f.color=color;f.life=f.max=.38f;fx.add(f);cameraShake=Math.max(cameraShake,7);}\n\n'''
