new_proj='''    private void updateProjectiles(float dt){\n        Iterator<Projectile> it=projectiles.iterator();while(it.hasNext()){Projectile q=it.next();q.life-=dt;q.prevX=q.x;q.prevY=q.y;if(q.life<=0){if(q.type==5)explodeProjectile(q);it.remove();continue;}\n            if(q.type==1&&!q.hostile){Enemy t=nearestEnemy(q.x,q.y);if(t!=null){float a=(float)Math.atan2(t.y-q.y,t.x-q.x);float tx=(float)Math.cos(a)*390,ty=(float)Math.sin(a)*390;q.vx+=(tx-q.vx)*Math.min(1,dt*3.4f);q.vy+=(ty-q.vy)*Math.min(1,dt*3.4f);q.angle=(float)Math.atan2(q.vy,q.vx);}}\n            q.x+=q.vx*dt;q.y+=q.vy*dt;if(q.type==5&&!q.hostile&&dist(q.x,q.y,q.targetX,q.targetY)<30){explodeProjectile(q);it.remove();continue;}\n            if(q.hostile){if(dist(q.x,q.y,px,py)<q.radius+49){damagePlayer(q.damage);if(q.type==7)explosionFx(q.x,q.y,Color.rgb(255,111,63),q.splash);else particleBurst(q.x,q.y,Color.rgb(255,88,54),8);it.remove();}}\n            else{Enemy hit=null;for(Enemy e:enemies){if(dist(q.x,q.y,e.x,e.y)<q.radius+e.radius){hit=e;break;}}if(hit!=null){damageEnemy(hit,q.damage);if(q.type==1||q.type==4){float factor=q.type==1?.45f:.32f;for(Enemy e:enemies)if(e!=hit&&dist(q.x,q.y,e.x,e.y)<q.splash)damageEnemy(e,q.damage*factor);explosionFx(q.x,q.y,q.type==1?Color.rgb(255,150,50):Color.rgb(180,95,255),q.splash);}else particleBurst(q.x,q.y,q.type==2?Color.rgb(255,204,110):Color.rgb(70,235,219),5);it.remove();}}\n        }\n    }\n    private void explodeProjectile(Projectile q){for(Enemy e:enemies)if(dist(q.x,q.y,e.x,e.y)<q.splash)damageEnemy(e,q.damage*(1-dist(q.x,q.y,e.x,e.y)/Math.max(1,q.splash)*.45f));explosionFx(q.x,q.y,Color.rgb(255,205,93),q.splash);}\n'''
